function shLink(page, headingText){
  const insts = page.findAll(n=>n.type==="INSTANCE" && n.name==="SectionHeading");
  for (const inst of insts) {
    const h = inst.findOne(n=>n.name==="heading");
    if (h && h.characters === headingText) {
      return inst.findOne(n=>n.name==="Link" && n.type==="FRAME");
    }
  }
  return null;
}
