const PAGES = {
  "01_Frontpage":"14:80", "02_Magazine":"16:255", "03_Magazine_Post":"17:451",
  "04_Podcast":"18:545", "05_Podcast_Post":"19:640", "06_Authors":"20:735", "07_Author_Profile":"21:834",
};
const summary = {};
for (const [pname, pid] of Object.entries(PAGES)) {
  const page = await figma.getNodeByIdAsync(pid);
  let count = 0;
  function walk(n){
    if (n.reactions && n.reactions.length) count += n.reactions.length;
    if (n.type !== "INSTANCE" && "children" in n) { for (const c of n.children) walk(c); }
    else if (n.type === "INSTANCE" && "children" in n) { for (const c of n.children) walk(c); }
  }
  walk(page);
  summary[pname] = count;
}
return summary;
